def format_set(s):
    if not s:
        return "set()"
    return "{" + ", ".join(repr(x) for x in sorted(s)) + "}"


def parse_set(line):
    if line.strip() == "":
        return set()
    items = [item.strip() for item in line.split(",")]
    return set(item for item in items if item)


